use strict;
use warnings;

open my $fh, '<', '.env.test' or die "Cannot open .env.test: $!";
my %env;

while (my $line = <$fh>) {
    chomp $line;
    next if $line =~ /^\s*#/ || $line =~ /^\s*$/;
    if ($line =~ /^([A-Z_]+)=(.*)$/) {
        $env{$1} = $2;
    }
}
close $fh;

# Simple JSON encoding
print "{";
my @pairs;
foreach my $key (sort keys %env) {
    my $val = $env{$key};
    $val =~ s/\\/\\\\/g;
    $val =~ s/"/\\"/g;
    push @pairs, "\"$key\":\"$val\"";
}
print join(",", @pairs);
print "}\n";
EOF

